/**
 * Immutable schema-safe copy of a stored advisory's complete context.
 */
export type ModeloReconciliationAdvisoryProjection = {
  code: string;
  message: string;
  context: [string, string][];
};

/**
 * One disagreement between work unit / profile / computed state and evidence.
 *
 * `diff_kind` is the closed category (header field, filed total, or per-
 * casilla). `kind` remains the specific mismatch token (`modelo_mismatch`,
 * `total_ingresar_mismatch`, `casilla_value_mismatch`,
 * `casilla_missing_in_filed`, `casilla_extra_in_filed`, …). A `total` or
 * `casilla` diff carries the reconciling verification expectation's /
 * casilla's `legal_refs` / `source_refs` so the divergence surfaces with its
 * legal grounding (`aeat-calculation-grounding`); header diffs carry empty
 * grounding. For a `casilla` diff, `field_name` is the casilla id and
 * `work_unit_value` / `evidence_value` carry the computed / filed decimal
 * strings (empty when the corresponding side carried no value, per
 * `CasillaDivergenceKind`).
 */
export type ModeloReconciliationDiff = {
  field_name: string;
  work_unit_value: string;
  evidence_value: string;
  kind: string;
  diff_kind: ModeloReconciliationDiffKind;
  legal_refs: LegalRefId[];
  source_refs: SourceRefId[];
};

/**
 * Closed category for a `ModeloReconciliationDiff`.
 *
 * `header_field` — a receipt-identity disagreement (modelo, ejercicio, period,
 * tax id). `total` — a filed-amount disagreement between the receipt total and
 * the canonical computed result casilla. `casilla` — a per-casilla value
 * disagreement between the persisted computed revision and a filed
 * declaración, emitted for modelos enrolled under `DECLARATION_RECONCILE_ROLE`
 * (`detect_casilla_divergences`).
 */
export type ModeloReconciliationDiffKind = "header_field" | "total" | "casilla";

/**
 * Closed external-evidence labels accepted by reconciliation commands.
 *
 * `DECLARATION` performs casilla-level reconciliation for modelos enrolled
 * under `DECLARATION_RECONCILE_ROLE`; other modelos raise
 * `ReconciliationDeclaracionSourceUnsupportedError`.
 */
export type ModeloReconciliationEvidenceKind = "justificante" | "declaration";

/**
 * Closed immutable advisory fields with lossless context key/value pairs.
 */
export type ModeloReconciliationImportAdvisoryProjection = {
  code: string;
  message: string;
  context: [string, string][];
};

