/**
 * Address a captured receipt and one work unit in one bound profile.
 *
 * The work unit is named either by its identifier, whole or in the short form
 * the work listings show, or by `modelo`, `year` and `period` with an optional
 * registry `revision`; the operation resolves it as every work command does.
 * The evidence is named by the identifier the capture returned: `snapshot_id`
 * from a receipt capture, `observation_id` from a filed declaration capture.
 * `actor` is recorded as sent for a person's session. An automation's session
 * is recorded under its own session label, whatever the request carries.
 */
export type ModeloReconciliationPullRequest = {
  profile_id: string;
  work_unit_id?: string | null;
  modelo?: string | null;
  year?: number | null;
  period?: PublicPeriod | null;
  revision?: RevisionId | null;
  calculation_revision_id?: CalculationRevisionId | null;
  snapshot_id?: SnapshotId | null;
  observation_id?: SnapshotId | null;
  source_kind?: ModeloReconciliationEvidenceKind;
  actor?: string;
};

/**
 * Closed verdict catalogue for `ModeloReconciliationReport`.
 *
 * Closed set: `matches` / `mismatches`. A reconcile that reaches a report has
 * already parsed its evidence; an unparseable justificante is surfaced as the
 * typed `ReconciliationEvidenceInvalidError` refusal
 * (`REFUSED_RECONCILIATION_EVIDENCE_INVALID`) before any report is built, so
 * there is no `evidence_invalid` verdict shell. Any expansion requires a
 * design decision and must not add shells.
 */
export type ModeloReconciliationVerdict = "matches" | "mismatches";

